// Render-only flight pose; sampled from displayed positions, including network interpolation.
const apachePoses=new Map();
function apacheFlightPose(u,time,now){
  let p=apachePoses.get(u.id);
  if(!p||time<p.time||Math.hypot(u.x-p.x,u.y-p.y)>160){
    p={x:u.x,y:u.y,time,now,roll:0,pitch:0,vx:0,vy:0};apachePoses.set(u.id,p);
    if(apachePoses.size>16)for(const [id,v] of apachePoses)if(now-v.now>10)apachePoses.delete(id);
    return p;
  }
  const dt=time-p.time,frame=Math.max(0,Math.min(.1,now-p.now));
  if(dt>0){p.vx=(u.x-p.x)/dt;p.vy=(u.y-p.y)/dt;p.x=u.x;p.y=u.y;p.time=time;p.sampled=now;}
  if(now-(p.sampled??now)>.15)p.vx=p.vy=0;
  const speed=Math.max(1,u.speed||220),limit=v=>Math.max(-1,Math.min(1,v));
  const roll=limit((-Math.sin(u.angle)*p.vx+Math.cos(u.angle)*p.vy)/speed);
  const pitch=limit((Math.cos(u.angle)*p.vx+Math.sin(u.angle)*p.vy)/speed);
  const ease=1-Math.exp(-frame/.16);
  p.roll+=(roll-p.roll)*ease;p.pitch+=(pitch-p.pitch)*ease;p.now=now;
  return p;
}
function drawMinimalApache(ctx, x, y, angle, rotorAngle, teamColor = '#2b82c9', roll=0, pitch=0) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(angle);
  // Project the tilted fuselage without changing its actual world heading.
  ctx.transform(Math.cos(roll*.45),0,roll*.12,Math.cos(pitch*.28),roll*3,-pitch*2);

  // 1. Хвостовая балка и стабилизатор
  ctx.fillStyle = '#2d3748';
  ctx.fillRect(-3, 10, 6, 28);
  ctx.fillRect(-10, 34, 20, 4);

  // 2. Крылья-пилоны
  ctx.fillRect(-18, -4, 36, 6);
  ctx.fillStyle = '#1a202c';
  ctx.fillRect(-18, -6, 4, 10);
  ctx.fillRect(14, -6, 4, 10);

  // 3. Основной корпус
  ctx.fillStyle = teamColor;
  ctx.fillRect(-7, -14, 14, 26);

  // 4. Носовая часть
  ctx.beginPath();
  ctx.moveTo(-7, -14);
  ctx.lineTo(0, -26);
  ctx.lineTo(7, -14);
  ctx.closePath();
  ctx.fill();

  // 5. Остекление кабины
  ctx.fillStyle = '#63b3ed';
  ctx.fillRect(-3, -20, 6, 9);

  // 6. Несущий винт
  ctx.save();
  // The rotor hub leans with the aircraft above its fixed ground shadow.
  ctx.translate(roll*8,-pitch*6);
  ctx.scale(Math.cos(roll*.5),Math.cos(pitch*.35));
  ctx.rotate(rotorAngle);
  ctx.fillStyle = 'rgba(255, 255, 255, 0.7)';
  ctx.fillRect(-2, -32, 4, 64);
  ctx.fillRect(-32, -2, 64, 4);

  // 7. Радар Longbow
  ctx.fillStyle = '#1a202c';
  ctx.beginPath();
  ctx.arc(0, 0, 5, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
  ctx.restore();
}
