function drawBush(b){ctx.save();ctx.translate(b.x,b.y);ctx.fillStyle='#26412a';ctx.beginPath();ctx.ellipse(0,0,b.r,b.r,0,0,Math.PI*2);ctx.fill();for(let i=0;i<9;i++){const a=i*2.399963,x=Math.cos(a)*b.r*.48,y=Math.sin(a)*b.r*.42;ctx.fillStyle=i%2?'#3c5d36':'#355633';ctx.beginPath();ctx.ellipse(x,y,b.r*.37,b.r*.26,a,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#61834a66';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(x-7,y+5);ctx.lineTo(x,y-7);ctx.lineTo(x+6,y+1);ctx.stroke();}ctx.restore();}
