function drawMinimap(s){if(overview)return;const w=216,h=126,x=VW-w-12,y=12,scale=w/W;ctx.save();ctx.fillStyle='#15201fe8';ctx.fillRect(x,y,w,h);ctx.strokeStyle='#8d9b91';ctx.strokeRect(x,y,w,h);ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.beginPath();ctx.rect(0,0,W,H);ctx.clip();ctx.strokeStyle='#735d43';ctx.lineWidth=40;for(const road of DIRT_ROADS){ctx.beginPath();ctx.moveTo(road[0].x,road[0].y);ctx.lineTo(road[1].x,road[1].y);ctx.stroke();}ctx.strokeStyle='#74756c';ctx.lineWidth=35;for(const route of ROUTES){ctx.beginPath();route.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();}for(const b of s.bushes||BUSHES)circle(b.x,b.y,b.r,'#456439');for(const e of s.entities){circle(e.x,e.y,e.kind==='tank'?36:e.kind==='infantry'?13:23,color(e.team));}if(s.point.mode==='vision'){ctx.strokeStyle=s.point.activeUntil?color(s.point.team):s.point.available?'#ffe09a':'#c8cbb1';ctx.lineWidth=s.point.available?20:10;ctx.setLineDash(s.point.available||s.point.activeUntil?[]:[20,20]);circle(s.point.x,s.point.y,s.point.r);ctx.setLineDash([]);}ctx.strokeStyle='#e2e8dc';ctx.lineWidth=8;ctx.strokeRect(camera.x,camera.y,VW/camera.zoom,PH/camera.zoom);ctx.restore();ctx.font='12px system-ui';ctx.fillStyle='#d5decd';ctx.textAlign='right';ctx.fillText('M — общий вид · Y — сменить сторону',x+w,y+h+17);ctx.restore();}
function switchSide(){if(view.selection?.active)return;if(network){$('netStatus').textContent='Переключение Y доступно в одиночной демке.';return;}game.command(team,{type:'smoke',held:false});team=1-team;view=game.snapshot(team);$('mode').textContent='Одиночный режим · '+factionName(team);}

function updateStatUpgrades(s){const p=s.me,box=$('statUpgrades');box.hidden=!!s.spectator||!!s.selection?.active;const names={damage:'Урон всего оружия',range:'Дальность атаки',speed:'Скорость движения',health:'Максимальное здоровье',rate:'Скорострельность'};for(const key of Object.keys(names)){const button=$('stat-'+key),rank=p.statRanks?.[key]||0,factor=((s.balance||B).statProgression?.initial??.75)+rank*((s.balance||B).statProgression?.step??.1);button.disabled=false;button.setAttribute('aria-disabled',String(!(p.statPoints>0)||rank>=6||!!s.over));button.title='';button.dataset.tooltip=names[key]+' '+rank+'/6';for(let i=0;i<6;i++)$('stat-dot-'+key+'-'+i).className=i<rank?'is-filled':'';button.setAttribute('aria-label',button.title);}$('statPoints').textContent=p.statPoints>0?'Улучшения: '+p.statPoints:'Улучшения';}
