for(const key of ['damage','range','speed','health','rate'])$('stat-'+key).onclick=()=>{if($('stat-'+key).getAttribute('aria-disabled')!=='true')send({type:'statUpgrade',stat:key});};
function updateHealthRegen(s){const p=s.me,b=s.balance||B;let rate=0;const active=q=>q.repair&&q.repair.cancelAt===null&&s.time>=q.repair.started+(q.repair.warmup??q.repairWarmup);if(p.tank.hp>0&&p.tank.hp<p.tank.max){const zone=(s.repairZones||[]).find(z=>z.team===p.team&&distance(z,p.tank)<=z.r);if(zone)rate=zone.rate;else if(p.vehicle!=='apache'){if(s.time-p.lastDamageAt>=regenerationConfig(p.vehicle,b).delay)rate+=regenerationConfig(p.vehicle,b).hpPerSecond;if(active(p))rate+=p.repairRate;}for(const ally of s.players||[]){const service=ally.skills?.bService;if(service&&ally.enabled&&ally.id!==p.id&&ally.team===p.team&&ally.tank.hp>0&&active(ally)&&distance(ally.tank,p.tank)<=service.radius)rate+=ally.repairRate*service.percent/100;}}let el=$('healthRegen');if(!el){el=document.createElement('span');el.id='healthRegen';const wrap=document.createElement('div');wrap.className='health-bar-wrap';$('playerHealth').replaceWith(wrap);wrap.append($('playerHealth')||document.createElement('span'));}el.textContent=rate>0?'+'+Number(rate.toFixed(1))+' hp/с':'';el.hidden=!(rate>0);$('recovery').textContent='';}
