function updateRecentXp(s){const p=s.me,now=performance.now(),max=LEVELS[p.level]||LEVELS[LEVELS.length-1];if(!recentXpState||recentXpState.id!==p.id||recentXpState.vehicle!==p.vehicle||s.time<recentXpState.time){recentXpState={id:p.id,vehicle:p.vehicle,xp:p.xp,time:s.time,segments:[]};}const state=recentXpState;if(p.xp>state.xp)state.segments.push({from:state.xp,to:p.xp,at:now});if(p.xp<state.xp)state.segments=[];state.xp=p.xp;state.time=s.time;state.segments=state.segments.filter(v=>now-v.at<2200);const stops=state.segments.flatMap(v=>{const fade=Math.max(0,1-(now-v.at)/2200),color='rgb('+Math.round(157+54*fade)+','+Math.round(92+59*fade)+','+Math.round(101+59*fade)+')';return [color+' '+Math.min(100,v.from/max*100)+'%',color+' '+Math.min(100,v.to/max*100)+'%'];});$('xpRecent').style.background=stops.length?'linear-gradient(to right,transparent 0%,transparent '+Math.min(100,state.segments[0].from/max*100)+'%,'+stops.join(',')+',transparent '+Math.min(100,state.segments.at(-1).to/max*100)+'%)':'none';}
