 if(document.pointerLockElement===canvas){pointer??={x:b.left+b.width/2,y:b.top+b.height/2};pointer.x=Math.max(b.left,Math.min(b.right,pointer.x+e.movementX));pointer.y=Math.max(b.top,Math.min(b.bottom,pointer.y+e.movementY));}
