canvas.addEventListener('pointercancel',()=>{trigger=false;control(performance.now(),true);});
window.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA'].includes(e.target.tagName))return;if(['KeyW','KeyA','KeyS','KeyD'].includes(e.code)){e.preventDefault();if(view.selection?.active)return;heldKeys.add(e.code);control(performance.now(),true);}});
