 const backing=FrontlinePresentation.renderSize(rect.width,rect.height,dpr,fullscreen);const logicalWidth=fullscreen?Math.max(1,Math.round(VH*rect.width/Math.max(1,rect.height))):1200,width=backing.width,height=backing.height;
